FRAMES: the images that follow are ${prep.frame_urls:isEmpty():ifElse('0', ${prep.frame_urls:replaceAll('[^,]', ''):length():plus(1)})} frames from the clip in time order."}${prep.image_parts:length():gt(2):ifElse(${prep.image_parts:substringAfter('['):substringBeforeLast(']'):prepend(',')}, '')}]}]}
